// undefined or null arrives where the type says Dog. The type checker accepts every line under `strict`: there is no `any`, no cast, no user type guard and no declaration without a body.
// Each way for the value to arrive is crossed with the places where it goes next. A compiled program prints what plain Bun prints, or throws a TypeError where a rule of the compiler says so. It never reads a value as something that it is not.
function t(name: string, f: () => unknown) { let r: string; try { r = String(f()); } catch (e) { r = "threw " + (e instanceof Error ? e.name : typeof e); } console.log(name, r); }
class Animal { name = "animal"; }
class Dog extends Animal { legs = 4; bark(): number { return this.legs * 2; } }
class Cat extends Animal { lives = "nine"; }
t("an element past the end: a typed field", () => { const list: Dog[] = []; const bad = list[0]; class Pen { pet: Dog = new Dog(); legs(): number { return this.pet.legs + 1; } } const pen = new Pen(); pen.pet = bad; return pen.legs(); });
t("an element past the end: an array element", () => { const list: Dog[] = []; const bad = list[0]; const pack: Dog[] = [new Dog()]; pack.push(bad); let total = 0; for (const d of pack) total += d.legs; return total; });
t("an element past the end: a parameter of a hot function", () => { const list: Dog[] = []; const bad = list[0]; const legsOf = (d: Dog): number => d.legs; let total = 0; for (let i = 0; i < 2000; i++) total += legsOf(bad); return total; });
t("an element past the end: a typed return", () => { const list: Dog[] = []; const bad = list[0]; const give = (): Dog => bad; return give().legs + 1; });
t("an element past the end: a map value", () => { const list: Dog[] = []; const bad = list[0]; const table = new Map<string, Dog>(); table.set("k", bad); const got = table.get("k"); return got === undefined ? "absent" : got.legs + 1; });
t("an element past the end: a captured variable", () => { const list: Dog[] = []; const bad = list[0]; let kept: Dog = new Dog(); const read = (): number => kept.legs + 1; kept = bad; return read(); });
t("an element past the end: arithmetic", () => { const list: Dog[] = []; const bad = list[0]; return [bad.legs + 1, bad.legs * 2, bad.legs | 0, bad.legs < 5].join(); });
t("an element past the end: a method call", () => { const list: Dog[] = []; const bad = list[0]; return bad.bark(); });
t("an element past the end: a store back into the heap", () => { const list: Dog[] = []; const bad = list[0]; bad.legs = 8; const crate: { pet: Dog } = { pet: bad }; return JSON.stringify(crate); });
