t("a generator resumed without a value: a parameter of a hot function", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; const legsOf = (d: Dog): number => d.legs; let total = 0; for (let i = 0; i < 2000; i++) total += legsOf(bad); return total; } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: a typed return", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; const give = (): Dog => bad; return give().legs + 1; } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: a map value", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; const table = new Map<string, Dog>(); table.set("k", bad); const got = table.get("k"); return got === undefined ? "absent" : got.legs + 1; } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: a captured variable", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; let kept: Dog = new Dog(); const read = (): number => kept.legs + 1; kept = bad; return read(); } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: arithmetic", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; return [bad.legs + 1, bad.legs * 2, bad.legs | 0, bad.legs < 5].join(); } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: a method call", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; return bad.bark(); } const it = g(); it.next(); return it.next().value; });
t("a generator resumed without a value: a store back into the heap", () => { function* g(): Generator<number, unknown, Dog> { const bad = yield 1; bad.legs = 8; const crate: { pet: Dog } = { pet: bad }; return JSON.stringify(crate); } const it = g(); it.next(); return it.next().value; });
